            externalIdInput.value =
                sourceUiState
                    .formExternalId;
        }

        if (tableBody) {
            if (
                sources.length === 0
            ) {
                tableBody.innerHTML =
                    '<tr>' +
                        '<td colspan="6">' +
                            '<div class="sources-empty">' +
                                '<strong>' +
                                    'Sin fuentes para mostrar' +
                                '</strong>' +
