    function renderQueryNavigation() {
        var view =
            normalizeQueryView(
                currentQueryView
            );

        currentQueryView =
            view;

        var buttons =
            document.querySelectorAll(
                '[data-query-view]'
            );

        buttons.forEach(
            function(button) {
                var buttonView =
                    normalizeQueryView(
                        button.getAttribute(
                            'data-query-view'
                        )
                    );

                button.classList.toggle(
                    'active',
                    buttonView === view
                );

                button.setAttribute(
                    'aria-current',
                    buttonView === view
                        ? 'page'
                        : 'false'
                );
            }
        );

        var panels =
            document.querySelectorAll(
                '[data-query-view-panel]'
            );

        panels.forEach(
            function(panel) {
                var panelView =
                    normalizeQueryView(
                        panel.getAttribute(
                            'data-query-view-panel'
                        )
                    );

                var active =
                    panelView === view;

                panel.classList.toggle(
                    'active',
                    active
                );

                panel.hidden =
                    !active;
            }
        );

        if (
            view === 'constructor'
        ) {
            renderCurrentView();
            return;
        }

        if (
            view === 'all'
        ) {
            renderLibrary();
            return;
        }

        if (
            view === 'sources'
        ) {
            renderSourcesManagement();
        }
    }


