    function quoteTerm(term) {
        return (
            '"' +
            String(term)
                .replace(
                    /\\/g,
                    '\\\\'
                )
                .replace(
                    /"/g,
                    '\\"'
                ) +
            '"'
        );
    }


    function buildGroupFormula(
        group
    ) {
        if (
            !group ||
            group.include.length === 0
        ) {
            return '';
        }

        var includeFormula =
            group.include
                .map(
                    quoteTerm
                )
                .join(
                    ' OR '
                );

        if (
            group.include.length > 1
        ) {
            includeFormula =
                '(' +
                includeFormula +
                ')';
        }

        var andFormula =
            group.and.length > 0
                ? ' AND ' +
                  group.and
                    .map(
                        quoteTerm
                    )
                    .join(
                        ' AND '
                    )
                : '';

        var excludeFormula =
            group.and_not.length > 0
                ? ' AND NOT (' +
                  group.and_not
                    .map(
                        quoteTerm
                    )
                    .join(
                        ' OR '
                    ) +
                  ')'
                : '';

        return (
            includeFormula +
            andFormula +
            excludeFormula
        );
    }


    function buildFormula() {
        var validGroups =
            groups.filter(
                function(group) {
                    return (
                        group &&
                        Array.isArray(
                            group.include
                        ) &&
                        group.include.length > 0
                    );
                }
            );

        if (
            validGroups.length === 0
        ) {
            return '';
        }

        var formula =
            validGroups
                .map(
                    function(group) {
                        return (
                            '(' +
                            buildGroupFormula(
                                group
                            ) +
                            ')'
                        );
                    }
                )
                .join(
                    ' OR '
                );

        if (
            validGroups.length === 1
        ) {
            formula =
                buildGroupFormula(
                    validGroups[0]
                );
        }

        return formula;
    }


    function getTotalTerms() {
        return groups.reduce(
            function(total, group) {
                return (
                    total +
                    group.include.length +
                    group.and.length +
                    group.and_not.length
                );
            },
            0
        );
    }


    function hasValidManualRules() {
        return (
            groups.length > 0 &&
            groups.every(
                function(group) {
                    return (
                        group.include
                            .length > 0
                    );
                }
            )
        );
    }


