    function getSelectedQuery(
        model
    ) {
        var drawerModel =
            model ||
            getModel();

        var selectedId =
            String(
                drawerModel.selectedQueryId ||
                ''
            ).trim();

        if (!selectedId) {
            return null;
        }

        return asArray(
            drawerModel.queries
        )
        .find(
            function(query) {
                return (
                    query &&
                    String(
                        query.id ||
                        ''
                    ) ===
                    selectedId
                );
            }
        ) ||
        null;
    }


    function getDrawerPosts(
        model
    ) {
        var drawerModel =
            model ||
            getModel();

        var selectedId =
            String(
                drawerModel.selectedQueryId ||
                ''
            ).trim();

        return asArray(
            drawerModel.drawerPosts
        )
        .filter(
            function(post) {
                if (!post) {
                    return false;
                }

                if (!selectedId) {
                    return true;
                }

                return (
                    String(
                        post.query_id ||
                        ''
                    ) ===
                    selectedId
                );
            }
        );
    }


    function getDrawerAnalytics(
        model
    ) {
        var drawerModel =
            model ||
            getModel();

        var selectedId =
            String(
                drawerModel.selectedQueryId ||
                ''
            ).trim();

        var analytics =
            asObject(
                drawerModel.drawerAnalytics
            );

        var analyticsQueryId =
            String(
                analytics.query_id ||
                ''
            ).trim();

        if (
            selectedId &&
            analyticsQueryId &&
            analyticsQueryId !==
            selectedId
        ) {
            return {};
        }

        return analytics;
    }


    function safeNumber(
        value
    ) {
        var number =
            Number(
                value ||
                0
            );

        return isFinite(number)
            ? number
            : 0;
    }


    function formatDrawerDateTime(
        value
    ) {
        if (!value) {
            return '—';
        }

        try {
            return new Intl.DateTimeFormat(
                'es-MX',
                {
                    day: '2-digit',
                    month: '2-digit',
                    year: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit'
                }
            ).format(
                new Date(value)
            );
        } catch (error) {
            return '—';
        }
    }


    function formatDrawerDay(
        value
    ) {
        if (!value) {
            return 'Sin fecha';
        }

        try {
            return new Intl.DateTimeFormat(
                'es-MX',
                {
                    day: '2-digit',
                    month: 'short',
                    year: 'numeric'
                }
            ).format(
                new Date(value)
            );
        } catch (error) {
            return String(
                value ||
                'Sin fecha'
            );
        }
    }


    function formatDrawerMetric(
        value
    ) {
        var number =
            safeNumber(value);

        try {
            return new Intl.NumberFormat(
                'es-MX',
                {
                    maximumFractionDigits:
                        2
                }
            ).format(
                number
            );
        } catch (error) {
            return String(
                number
            );
        }
    }


    function getDrawerLatestObservedAt(
        posts
    ) {
        var latest =
            null;

        posts.forEach(
            function(post) {
                var candidate =
                    post &&
                    (
                        post.metrics_last_observed_at ||
                        post.metrics_fetched_at ||
                        post.scraped_at ||
                        post.last_confirmed_at ||
                        post.matched_at
                    );

                if (!candidate) {
                    return;
                }

                var time =
                    new Date(
                        candidate
                    ).getTime();

                if (
                    !isNaN(time) &&
                    (
                        latest === null ||
                        time > latest
                    )
                ) {
                    latest = time;
                }
            }
        );

        return latest === null
            ? null
            : new Date(
                latest
            ).toISOString();
    }


    function getDrawerPlatformCounts(
        posts
    ) {
        var counts = {};

        posts.forEach(
            function(post) {
                var platform =
                    String(
                        post &&
                        post.platform ||
                        ''
                    )
                    .trim()
                    .toLowerCase();

                if (!platform) {
                    platform =
                        'sin_plataforma';
                }

                counts[platform] =
                    (
                        counts[platform] ||
                        0
                    ) + 1;
            }
        );

        var preferredOrder = [
            'facebook',
            'instagram',
            'threads'
        ];

        return Object.keys(
            counts
        )
        .sort(
            function(a, b) {
                var indexA =
                    preferredOrder
                        .indexOf(a);

                var indexB =
                    preferredOrder
                        .indexOf(b);

                if (
                    indexA === -1 &&
                    indexB === -1
                ) {
                    return a.localeCompare(
                        b,
                        'es',
                        {
                            sensitivity:
                                'base'
                        }
                    );
                }

                if (
                    indexA === -1
                ) {
                    return 1;
                }

                if (
                    indexB === -1
                ) {
                    return -1;
                }

                return (
                    indexA -
                    indexB
                );
            }
        )
        .map(
            function(platform) {
                return {
                    platform:
                        platform,

                    count:
                        counts[platform]
                };
            }
        );
    }


