    function renderDrawerBars(
        items,
        labelKey,
        valueKey
    ) {
        var list =
            Array.isArray(items)
                ? items
                : [];

        if (
            list.length === 0
        ) {
            return (
                '<div class="query-drawer-empty">' +
                    '<strong>' +
                        'Sin datos' +
                    '</strong>' +
                    '<span>' +
                        'No hay información suficiente para esta distribución.' +
                    '</span>' +
                '</div>'
            );
        }

        var maxValue =
            list.reduce(
                function(
                    maximum,
                    item
                ) {
                    return Math.max(
                        maximum,
                        safeNumber(
                            item &&
                            item[valueKey]
                        )
                    );
                },
                0
            );

        return (
            '<div class="query-drawer-bars">' +

                list.map(
                    function(item) {
                        var value =
                            safeNumber(
                                item &&
                                item[valueKey]
                            );

                        var width =
                            maxValue > 0
                                ? Math.max(
                                    3,
                                    (
                                        value /
                                        maxValue
                                    ) *
                                    100
                                )
                                : 0;

                        return (
                            '<div class="query-drawer-bar-row">' +

                                '<div class="query-drawer-bar-label">' +
                                    escapeHtml(
                                        item &&
                                        item[labelKey] ||
                                        '—'
                                    ) +
                                '</div>' +

                                '<div class="query-drawer-bar-track">' +

                                    '<div' +
                                        ' class="query-drawer-bar-fill"' +
                                        ' style="width:' +
                                            escapeHtml(
                                                width
                                            ) +
                                            '%"' +
                                    '></div>' +

                                '</div>' +

                                '<div class="query-drawer-bar-value">' +
                                    escapeHtml(
                                        formatDrawerMetric(
                                            value
                                        )
                                    ) +
                                '</div>' +

                            '</div>'
                        );
                    }
                )
                .join('') +

            '</div>'
        );
    }


