    function renderDrawerSection(
        model
    ) {
        var drawerModel =
            model ||
            getModel();

        var query =
            getSelectedQuery(
                drawerModel
            );

        var posts =
            getDrawerPosts(
                drawerModel
            );

        var analytics =
            getDrawerAnalytics(
                drawerModel
            );

        var content =
            document.getElementById(
                'queryDrawerSectionContent'
            );

        if (!content) {
            return;
        }

        var section =
            drawerState.activeSection ||
            'live';

        if (
            section === 'what'
        ) {
            content.innerHTML =
                renderDrawerWhat(
                    analytics,
                    query
                );

            return;
        }

        if (
            section === 'when'
        ) {
            content.innerHTML =
                renderDrawerWhen(
                    analytics
                );

            return;
        }

        if (
            section === 'amount'
        ) {
            content.innerHTML =
                renderDrawerAmount(
                    analytics
                );

            return;
        }

        if (
            section === 'how'
        ) {
            content.innerHTML =
                renderDrawerHow(
                    analytics
                );

            return;
        }

        if (
            section === 'who'
        ) {
            content.innerHTML =
                renderDrawerWho(
                    analytics
                );

            return;
        }

        if (
            section === 'where'
        ) {
            content.innerHTML =
                renderDrawerWhere(
                    analytics
                );

            return;
        }

        if (
            section === 'profiles'
        ) {
            content.innerHTML =
                renderDrawerProfiles(
                    analytics
                );

            return;
        }

        if (
            section === 'bot'
        ) {
            content.innerHTML =
                renderDrawerBot(
                    analytics
                );

            return;
        }

        if (
            section === 'streams'
        ) {
            content.innerHTML =
                renderDrawerStreams(
                    analytics
                );

            return;
        }

        content.innerHTML =
            renderDrawerLive(
                posts
            );
    }


    function renderDrawerNavigation() {
        var section =
            drawerState.activeSection ||
            'live';

        document
            .querySelectorAll(
                '[data-drawer-section]'
            )
            .forEach(
                function(button) {
                    var buttonSection =
                        String(
                            button.getAttribute(
                                'data-drawer-section'
                            ) ||
                            ''
                        );

                    var active =
                        buttonSection ===
                        section;

                    button.classList.toggle(
                        'active',
                        active
                    );

                    button.setAttribute(
                        'aria-current',
                        active
                            ? 'page'
                            : 'false'
                    );
                }
            );
    }


    function setDrawerSection(
        section
    ) {
        var allowed = [
            'live',
            'what',
            'when',
            'amount',
            'how',
            'who',
            'where',
            'profiles',
            'bot',
            'streams'
        ];

        var normalized =
            String(
                section ||
                ''
            )
            .trim()
            .toLowerCase();

        drawerState.activeSection =
            allowed.indexOf(
                normalized
            ) === -1
                ? 'live'
                : normalized;

        renderDrawerNavigation();
        renderDrawerSection();
    }


    async function openPostExternally(
        url
    ) {
        var normalized =
            String(
                url ||
                ''
            ).trim();

        if (
            !/^https?:\/\//i.test(
                normalized
            )
        ) {
            return;
        }

        try {
            await appsmith.updateModel({
                openPostUrl:
                    normalized
            });

            appsmith.triggerEvent(
                'onOpenPost'
            );
        } catch (error) {
            console.error(
                'No fue posible preparar la apertura externa de la publicación:',
                error
            );
        }
    }


    function renderQueryDrawer(
        model
    ) {
        var drawerModel =
            model ||
            getModel();

        var query =
            getSelectedQuery(
                drawerModel
            );

        var posts =
            getDrawerPosts(
                drawerModel
            );

        var analytics =
            getDrawerAnalytics(
                drawerModel
            );

        var liveData =
            asObject(
                analytics.live
            );

        var howData =
            asObject(
                analytics.how
            );

        var titleElement =
            document.getElementById(
                'queryDrawerTitle'
            );

        var statusElement =
            document.getElementById(
                'queryDrawerStatus'
            );

        var formulaElement =
            document.getElementById(
                'queryDrawerFormula'
            );

        var countElement =
            document.getElementById(
                'queryDrawerResultsCount'
            );

        var observedElement =
            document.getElementById(
                'queryDrawerObservedAt'
            );

        var platformCountsElement =
            document.getElementById(
                'queryDrawerPlatformCounts'
            );

        if (titleElement) {
            titleElement.textContent =
                query &&
                query.name
                    ? String(
                        query.name
                    )
                    : String(
                        drawerModel.selectedQueryName ||
                        'Consulta'
                    );
        }

        if (statusElement) {
            var status =
                String(
                    query &&
                    query.status ||
                    'active'
                )
                .toLowerCase();

            statusElement.textContent =
                status === 'inactive'
                    ? 'Inactiva'
                    : 'Activa';

            statusElement.classList.toggle(
                'inactive',
                status === 'inactive'
            );
        }

        if (formulaElement) {
            formulaElement.textContent =
                String(
                    query &&
                    query.formula_text ||
                    ''
                );
        }

        if (countElement) {
            countElement.textContent =
                String(
                    liveData.results_count != null
                        ? liveData.results_count
                        : posts.length
                );
        }

        if (observedElement) {
            observedElement.textContent =
                formatDrawerDateTime(
                    liveData.latest_observed_at ||
                    getDrawerLatestObservedAt(
                        posts
                    )
                );
        }

        if (
            platformCountsElement
        ) {
            var counts =
                asArray(
                    howData.by_platform
                );

            if (
                counts.length === 0
            ) {
                counts =
                    getDrawerPlatformCounts(
                        posts
                    )
                    .map(
                        function(item) {
                            return {
                                platform:
                                    item.platform,

                                posts:
                                    item.count
                            };
                        }
                    );
            }

            platformCountsElement
                .innerHTML =
                    counts.length
                        ? counts
                            .map(
                                function(item) {
                                    return (
                                        '<span class="query-drawer-platform-pill">' +
                                            escapeHtml(
                                                formatPlatformLabel(
                                                    item &&
                                                    item.platform ||
                                                    ''
                                                )
                                            ) +
                                            ' · ' +
                                            escapeHtml(
                                                formatDrawerMetric(
                                                    item &&
                                                    item.posts
                                                )
                                            ) +
                                        '</span>'
                                    );
                                }
                            )
                            .join('')
                        : (
                            '<span class="query-drawer-platform-pill">' +
                                'Sin resultados' +
                            '</span>'
                        );
        }

        renderDrawerNavigation();

        renderDrawerSection(
            drawerModel
        );
    }


    function openQueryDrawer(
        query
    ) {
        ensureDrawerUi();

        var overlay =
            document.getElementById(
                'queryDrawerOverlay'
            );

        if (!overlay) {
            return;
        }

        drawerState.open =
            true;

        drawerState.activeSection =
            'live';

        overlay.hidden =
            false;

        overlay.setAttribute(
            'aria-hidden',
            'false'
        );

        renderQueryDrawer();

        document.body
            .classList.add(
                'query-drawer-open'
            );

        requestAnimationFrame(
            function() {
                if (
                    !drawerState.open
                ) {
                    return;
                }

                overlay.classList.add(
                    'open'
                );

                var closeButton =
                    overlay.querySelector(
                        '.query-drawer-close'
                    );

                if (closeButton) {
                    closeButton.focus();
                }
            }
        );
    }


    function closeQueryDrawer() {
        var overlay =
            document.getElementById(
                'queryDrawerOverlay'
            );

        if (
            !overlay ||
            !drawerState.open
        ) {
            return;
        }

        drawerState.open =
            false;

        overlay.classList.remove(
            'open'
        );

        overlay.setAttribute(
            'aria-hidden',
            'true'
        );

        document.body
            .classList.remove(
                'query-drawer-open'
            );

        setTimeout(
            function() {
                if (
                    !drawerState.open
                ) {
                    overlay.hidden =
                        true;
                }
            },
            260
        );
    }


    async function selectSavedQuery(
        queryId
    ) {
        var id =
            String(
                queryId ||
                ''
            ).trim();

        if (!id) {
            return;
        }

        var query =
            getQueries()
                .find(
                    function(item) {
                        return (
                            item &&
                            String(
                                item.id ||
                                ''
                            ) ===
                            id
                        );
                    }
                );

        if (!query) {
            return;
        }

        var name =
            String(
                query.name ||
                ''
            );

        lastSelectedQueryIdValue =
            id;

        await appsmith.updateModel({
            selectedQueryId:
                id,

            selectedQueryName:
                name
        });

        renderLibrary();

        openQueryDrawer(
            query
        );

        appsmith.triggerEvent(
            'onSelectQuery'
        );
    }


