    function hideAllViews() {
        var home =
            document.getElementById(
                'constructorHome'
            );

        if (home) {
            home.hidden =
                true;
        }

        var views =
            document.querySelectorAll(
                '.wizard-view'
            );

        views.forEach(
            function(view) {
                view.hidden =
                    true;
            }
        );
    }


    function renderModeSelector(
        mode
    ) {
        var selector =
            document.getElementById(
                'constructorModeSelector'
            );

        if (!selector) {
            return;
        }

        if (
            mode === 'home'
        ) {
            selector.classList.remove(
                'visible'
            );

            return;
        }

        selector.classList.add(
            'visible'
        );

        var buttons =
            selector.querySelectorAll(
                '[data-mode]'
            );

        buttons.forEach(
            function(button) {
                var buttonMode =
                    button.getAttribute(
                        'data-mode'
                    );

                button.classList.toggle(
                    'active',
                    buttonMode ===
                    mode
                );
            }
        );
    }


    function setWizardLabels(
        mode
    ) {
        var step1Title =
            document.getElementById(
                'wizardStep1Title'
            );

        var step1Subtitle =
            document.getElementById(
                'wizardStep1Subtitle'
            );

        var step2Title =
            document.getElementById(
                'wizardStep2Title'
            );

        var step2Subtitle =
            document.getElementById(
                'wizardStep2Subtitle'
