    function renderStepper(
        mode,
        step
    ) {
        var stepper =
            document.getElementById(
                'constructorWizard'
            );

        if (!stepper) {
            return;
        }

        stepper.hidden =
            mode === 'home';

        if (
            mode === 'home'
        ) {
            return;
        }

        var steps =
            stepper.querySelectorAll(
                '.wizard-step'
            );

        steps.forEach(
            function(element) {
                var number =
                    parseInt(
                        element.getAttribute(
                            'data-step'
                        ),
                        10
                    );

                element.classList.toggle(
                    'active',
                    number === step
                );

                element.classList.toggle(
                    'completed',
                    number < step
                );
            }
        );

        var lines =
            stepper.querySelectorAll(
                '.wizard-line'
            );

        lines.forEach(
            function(line, index) {
                line.classList.toggle(
                    'completed',
                    index + 1 <
                    step
                );
            }
        );
    }


    function getOperatorTerms(
        group,
        operator
    ) {
        if (
            !group
        ) {
            return [];
        }

        if (
            operator === 'include'
        ) {
            return group.include;
        }

        if (
            operator === 'and'
        ) {
            return group.and;
        }

        if (
            operator === 'and_not'
        ) {
            return group.and_not;
        }

        return [];
    }


    function getOperatorChipClass(
        operator
    ) {
        if (
            operator === 'and'
        ) {
            return 'and';
        }

        if (
            operator === 'and_not'
        ) {
            return 'exclude';
        }

        return 'include';
    }


    function getEmptyTermsText(
        operator
    ) {
        if (
            operator === 'and'
        ) {
            return 'Sin condiciones adicionales.';
        }

        if (
            operator === 'and_not'
        ) {
            return 'Sin exclusiones.';
        }

        return 'Agrega al menos una palabra o frase.';
    }


    function renderTerms(
        group,
        operator
    ) {
        var terms =
            getOperatorTerms(
                group,
                operator
            );

        if (
            terms.length === 0
        ) {
            return (
                '<span class="manual-term-empty">' +
                    escapeHtml(
                        getEmptyTermsText(
                            operator
                        )
                    ) +
                '</span>'
            );
        }

        return terms
            .map(
                function(term) {
                    return (
                        '<span class="manual-term-chip ' +
                            getOperatorChipClass(
                                operator
                            ) +
                        '">' +
                            '<span>' +
                                escapeHtml(
                                    term
                                ) +
                            '</span>' +
                            '<button' +
                                ' type="button"' +
                                ' data-remove-term="' +
                                    escapeHtml(
                                        operator
                                    ) +
                                '"' +
                                ' data-group-no="' +
                                    escapeHtml(
                                        group.group_no
                                    ) +
                                '"' +
                                ' data-term-value="' +
                                    escapeHtml(
                                        term
                                    ) +
                                '"' +
                                ' aria-label="Eliminar término"' +
                            '>' +
                                '×' +
                            '</button>' +
                        '</span>'
                    );
                }
            )
            .join('');
    }


    function renderRuleRow(
        group,
