    function formatPlatformLabel(
        value
    ) {
        var normalized =
            String(
                value ||
                ''
            )
            .trim()
            .toLowerCase();

        if (
            normalized === 'facebook'
        ) {
            return 'Facebook';
        }

        if (
            normalized === 'instagram'
        ) {
            return 'Instagram';
        }

        if (
            normalized === 'threads'
        ) {
            return 'Threads';
        }

        if (
            normalized === 'youtube'
        ) {
            return 'YouTube';
        }

        if (
            normalized === 'tiktok'
        ) {
            return 'TikTok';
        }

        if (!normalized) {
            return 'Plataforma';
        }

        return normalized
            .charAt(0)
            .toUpperCase() +
            normalized.slice(1);
    }


