    function normalizeAiProposal(
        proposal
    ) {
        var normalized = {
            groups: [],
            target_ids: [],
            use_web: false
        };

        if (
            !proposal ||
            typeof proposal !==
            'object'
        ) {
            return normalized;
        }

        var proposedGroups =
            Array.isArray(
                proposal.groups
            )
                ? proposal.groups
                : [];

        normalized.groups =
            proposedGroups
                .slice(
                    0,
                    getMaxGroups()
                )
                .map(
                    normalizeGroup
                )
                .filter(
                    function(group) {
                        return (
                            group.include
                                .length > 0
                        );
                    }
                );

        if (
            normalized.groups.length === 0
        ) {
            normalized.groups = [
                createEmptyGroup(1)
            ];
        }

        var allowedTargetIds =
            getSelectableTargets()
                .map(
                    function(target) {
                        return String(
                            target.id
                        );
                    }
                );

        normalized.target_ids =
            (
                Array.isArray(
                    proposal.target_ids
                )
                    ? proposal.target_ids
                    : []
            )
            .map(
                function(id) {
                    return String(id);
                }
            )
            .filter(
                function(id) {
                    return (
                        allowedTargetIds
                            .indexOf(id) !==
                        -1
                    );
                }
            );

        normalized.use_web =
            proposal.use_web === true;

        return normalized;
    }


    async function applyAiResponse(
        response
    ) {
        aiRequestPending =
            false;

        if (
            response &&
            response.needs_clarification ===
            true
        ) {
            aiFeedbackMessage =
                String(
                    response.clarification_question ||
                    'Necesito más información para construir la consulta.'
                );

            aiWarnings =
                Array.isArray(
                    response.warnings
                )
                    ? response.warnings
                    : [];

            currentStep = 1;

            renderCurrentView();

            return;
        }

        if (
            !response ||
            response.ok !== true
        ) {
            aiFeedbackMessage =
                String(
                    response &&
                    response.error ||
                    'No fue posible generar una propuesta.'
                );

            aiWarnings =
                Array.isArray(
                    response &&
                    response.warnings
                )
                    ? response.warnings
                    : [];

            currentStep = 1;

            renderCurrentView();

            return;
        }

        var proposal =
            normalizeAiProposal(
                response.proposal ||
                response
            );

        groups =
            proposal.groups;

        selectedTargetIds =
            proposal.target_ids;

        useWeb =
            proposal.use_web;

        aiFeedbackMessage =
            '';

        aiWarnings =
            Array.isArray(
                response.warnings
            )
                ? response.warnings
                : [];

        aiDraftInstruction =
            null;

        var groupsJson =
            JSON.stringify(
                groups
            );

        var targetIdsJson =
            JSON.stringify(
                selectedTargetIds
            );

        lastGroupsValue =
            groupsJson;

        lastTargetIdsValue =
            targetIdsJson;

        lastUseWebValue =
            String(
                useWeb
            );

        currentStep =
            2;

        await appsmith.updateModel({
            constructor_mode:
                'ai',

            constructor_step:
                2,

            query_groups_json:
                groupsJson,

            query_target_ids_json:
                targetIdsJson,

            query_use_web:
                useWeb,

            query_formula:
                buildFormula(),

            ai_proposal_json:
                JSON.stringify(
                    response.proposal ||
                    response
                ),

            ai_explanation:
                String(
                    response.explanation ||
                    ''
                ),

            ai_generated:
                true
        });

        renderCurrentView();
    }


    function renderCurrentView() {
        var mode =
            getMode();

        var step =
            getStep();

        currentMode =
            mode;

        currentStep =
            step;

        setWizardLabels(
            mode
        );

        renderModeSelector(
            mode
        );

        renderStepper(
            mode,
            step
        );

        hideAllViews();

        if (
            mode === 'home'
        ) {
            var home =
                document.getElementById(
                    'constructorHome'
                );

            if (home) {
                home.hidden =
                    false;
            }

            return;
        }

        var element =
            getViewElement(
                mode,
                step
            );

        if (!element) {
            return;
        }

        element.hidden =
            false;

        if (
            mode === 'manual'
        ) {
            if (
                step === 1
            ) {
                renderManualStep1(
                    element
                );

                return;
            }

            if (
                step === 2
            ) {
                renderManualStep2(
                    element
                );

                return;
            }

            if (
                step === 3
            ) {
                renderManualStep3(
                    element
                );

                return;
            }

            if (
                step === 4
            ) {
                renderManualStep4(
                    element
                );
            }

            return;
        }

        if (
            mode === 'ai'
        ) {
            if (
                step === 1
            ) {
                renderAiStep1(
                    element
                );

                return;
            }

            if (
                step === 2
            ) {
                renderAiStep2(
                    element
                );

                return;
            }

            if (
                step === 3
            ) {
                renderAiStep3(
                    element
                );

                return;
            }

            if (
                step === 4
            ) {
                renderAiStep4(
                    element
                );
            }
        }
    }


    function findGroup(
        groupNo
    ) {
        var number =
            parseInt(
                groupNo,
                10
            );

        if (
            isNaN(number)
        ) {
            return null;
        }

        return groups.find(
            function(group) {
                return (
                    group.group_no ===
                    number
                );
            }
        ) ||
        null;
    }


    function termExists(
        terms,
        candidate
    ) {
        var normalized =
            String(
                candidate ||
                ''
            )
            .trim()
            .toLocaleLowerCase(
                'es'
            );

        return terms.some(
            function(term) {
                return (
                    String(term)
                    .trim()
                    .toLocaleLowerCase(
                        'es'
                    ) ===
                    normalized
                );
            }
        );
    }


    async function addTerm(
        button
    ) {
        var groupNo =
            button.getAttribute(
                'data-group-no'
            );

        var operator =
            button.getAttribute(
                'data-add-term'
            );

        var input =
            document.querySelector(
                '.manual-term-input' +
                '[data-group-no="' +
                groupNo +
                '"]' +
                '[data-term-input="' +
                operator +
                '"]'
            );

        if (!input) {
            return;
        }

        var value =
            String(
                input.value ||
                ''
            ).trim();

        if (!value) {
            return;
        }

        var group =
            findGroup(
                groupNo
            );

        if (!group) {
            return;
        }

        var terms =
            getOperatorTerms(
                group,
                operator
            );

        if (
            termExists(
                terms,
                value
            )
        ) {
            input.value =
                '';

            return;
        }

        terms.push(
            value
        );

        input.value =
            '';

        await syncQueryPayload();

        renderCurrentView();
    }


    async function removeTerm(
        button
    ) {
        var group =
            findGroup(
                button.getAttribute(
                    'data-group-no'
                )
            );

        if (!group) {
            return;
        }

        var operator =
            button.getAttribute(
                'data-remove-term'
            );

        var value =
            String(
                button.getAttribute(
                    'data-term-value'
                ) ||
                ''
            );

        var terms =
            getOperatorTerms(
                group,
                operator
            );

        var index =
            terms.indexOf(
                value
            );

        if (
            index === -1
        ) {
            return;
        }

        terms.splice(
            index,
            1
        );

        await syncQueryPayload();

        renderCurrentView();
    }


    async function addGroup() {
        if (
            groups.length >=
            getMaxGroups()
        ) {
            return;
        }

        groups.push(
            createEmptyGroup(
                groups.length + 1
            )
        );

        await syncQueryPayload();

        renderCurrentView();
    }


    async function toggleTarget(
        targetId
    ) {
        var id =
            String(
