            );

        var instruction =
            input
                ? String(
                    input.value ||
                    ''
                ).trim()
                : String(
                    getAiInstruction()
                ).trim();

        if (
            aiRequestPending ||
            instruction.length < 20 ||
            instruction.length > 1500
        ) {
            return;
