        aiRequestPending =
            true;

        aiGenerateArmed =
            true;

        aiGenerateInstruction =
            instruction;

        aiFeedbackMessage =
            '';

        aiDraftInstruction =
            instruction;

        renderCurrentView();

        await appsmith.updateModel({
            ai_instruction:
                instruction
        });
