                'Escape' &&
                drawerState.open
            ) {
                event.preventDefault();

                closeQueryDrawer();

                return;
            }

            var queryCard =
                event.target.closest(
                    '[data-select-query-id]'
                );

            var interactiveControl =
                event.target.closest(
                    'button, input, select, textarea, a'
                );

            if (
                queryCard &&
                !interactiveControl &&
                (
                    event.key === 'Enter' ||
                    event.key === ' '
                )
            ) {
                event.preventDefault();

                selectSavedQuery(
                    queryCard.getAttribute(
                        'data-select-query-id'
                    )
                );

                return;
            }

            if (
                event.key !==
                'Enter'
            ) {
                return;
            }

            if (
                event.target &&
                event.target.id ===
                'sourcesSearch'
            ) {
                event.preventDefault();

                if (
                    sourceSearchTimer
                ) {
                    clearTimeout(
                        sourceSearchTimer
