                return;
            }

            var createSourceButton =
                event.target.closest(
                    '#sourceCreateButton'
                );

            if (
                createSourceButton
            ) {
                event.preventDefault();

                createManagedSource();

                return;
            }

            var toggleSourceButton =
                event.target.closest(
                    '[data-source-toggle-id]'
                );

            if (
                toggleSourceButton
            ) {
                event.preventDefault();

                toggleManagedSource(
                    toggleSourceButton
                        .getAttribute(
                            'data-source-toggle-id'
                        )
                );

                return;
            }

            var deleteSourceButton =
                event.target.closest(
                    '[data-source-delete-id]'
                );

            if (
                deleteSourceButton
            ) {
                event.preventDefault();

                deleteManagedSource(
                    deleteSourceButton
                        .getAttribute(
                            'data-source-delete-id'
                        )
                );

                return;
            }

            var previousSourcesButton =
                event.target.closest(
                    '#sourcesPrevPage'
                );

            if (
                previousSourcesButton
            ) {
                event.preventDefault();

                changeSourcePage(
                    -1
                );

                return;
            }

            var nextSourcesButton =
                event.target.closest(
                    '#sourcesNextPage'
                );

            if (
                nextSourcesButton
            ) {
                event.preventDefault();

                changeSourcePage(
                    1
                );

                return;
            }

            var generateAiButton =
                event.target.closest(
                    '[data-generate-ai]'
                );

            if (
                generateAiButton
            ) {
                generateAiProposal();

                return;
            }

            var saveButton =
                event.target.closest(
                    '[data-save-query]'
                );

            if (
                saveButton
            ) {
                saveManualQuery();

                return;
            }

            var sourceTarget =
                event.target.closest(
                    '[data-source-target-id]'
                );

            if (
                sourceTarget
            ) {
                toggleTarget(
                    sourceTarget
                        .getAttribute(
                            'data-source-target-id'
                        )
                );

                return;
            }

            var webSource =
                event.target.closest(
                    '[data-toggle-web]'
                );

            if (
                webSource
            ) {
                toggleWeb();

                return;
            }

            var addTermButton =
                event.target.closest(
                    '[data-add-term]'
                );

            if (
                addTermButton
            ) {
                addTerm(
                    addTermButton
                );

                return;
            }

            var removeTermButton =
                event.target.closest(
                    '[data-remove-term]'
                );

            if (
                removeTermButton
            ) {
                removeTerm(
                    removeTermButton
                );

                return;
            }

            var addGroupButton =
                event.target.closest(
                    '[data-add-group]'
                );

            if (
                addGroupButton
            ) {
                addGroup();

                return;
            }

            var nextStepButton =
                event.target.closest(
                    '[data-next-step]'
                );

            if (
                nextStepButton
            ) {
                setStep(
                    nextStepButton
                        .getAttribute(
                            'data-next-step'
                        )
                );

                return;
            }

            var prevStepButton =
                event.target.closest(
                    '[data-prev-step]'
                );

            if (
                prevStepButton
            ) {
                setStep(
                    prevStepButton
                        .getAttribute(
                            'data-prev-step'
                        )
                );

                return;
            }

            var homeButton =
                event.target.closest(
                    '[data-nav-home]'
                );

            if (
                homeButton
            ) {
                resetConstructor();

                return;
            }

            var startModeButton =
                event.target.closest(
                    '[data-start-mode]'
                );

            if (
                startModeButton
            ) {
                setMode(
                    startModeButton
                        .getAttribute(
                            'data-start-mode'
                        )
                );

                return;
            }

            var modeButton =
                event.target.closest(
                    '[data-mode]'
                );

            if (
                modeButton
            ) {
                setMode(
                    modeButton
                        .getAttribute(
                            'data-mode'
                        )
                );

                return;
            }

            var newQueryButton =
                event.target.closest(
                    '#newQueryButton'
                );

            if (
                newQueryButton
            ) {
                resetConstructor();

                return;
            }

            var toggleStatusButton =
                event.target.closest(
                    '[data-toggle-query-status-id]'
                );

            if (
                toggleStatusButton
            ) {
                event.preventDefault();
                event.stopPropagation();

                toggleSavedQueryStatus(
                    toggleStatusButton
                        .getAttribute(
                            'data-toggle-query-status-id'
                        )
                );

                return;
            }

            var rerunButton =
                event.target.closest(
                    '[data-rerun-query-id]'
                );

            if (
                rerunButton
            ) {
                event.preventDefault();
                event.stopPropagation();

                rerunSavedQuery(
                    rerunButton
                        .getAttribute(
                            'data-rerun-query-id'
                        )
                );

                return;
            }

            var queryCard =
                event.target.closest(
                    '[data-select-query-id]'
                );

            if (
                queryCard
            ) {
                selectSavedQuery(
                    queryCard
                        .getAttribute(
                            'data-select-query-id'
                        )
                );

                return;
            }

            var paginationButton =
                event.target.closest(
                    '[data-action]'
                );

            if (
                !paginationButton
            ) {
                return;
            }

            var action =
                paginationButton
                    .getAttribute(
                        'data-action'
                    );

            if (
                action ===
                'prev-page'
            ) {
                if (
                    currentPage >
                    1
                ) {
                    currentPage -=
                        1;

                    renderLibrary();
                }

                return;
            }

            if (
                action ===
                'next-page'
            ) {
                var totalPages =
                    getTotalPages();

                if (
                    currentPage <
                    totalPages
                ) {
                    currentPage +=
                        1;

                    renderLibrary();
                }
            }
        }
    );


    var initialMode =
        String(
            getModel()
                .constructor_mode ||
            'home'
        )
        .trim()
        .toLowerCase();

    currentMode =
        initialMode === 'manual' ||
        initialMode === 'ai'
            ? initialMode
            : 'home';


    var initialStep =
        parseInt(
            getModel()
                .constructor_step ||
            0,
            10
        );

    currentStep =
        !isNaN(initialStep) &&
        initialStep >= 0 &&
        initialStep <= 4
            ? initialStep
            : 0;


    loadGroupsFromModel();
    loadSourcesFromModel();

    initializeSourceUiState(
        getModel()
    );

    ensureDrawerUi();

    renderLibrary();
    renderQueryNavigation();


    lastSourceManagementValue =
        getSourceManagementSignature(
            getModel()
        );

    lastQueriesValue =
        String(
            getModel().queries ||
            ''
        );

    lastTargetsValue =
        String(
            getModel().targets ||
            ''
        );

    lastModeValue =
        String(
            getModel()
                .constructor_mode ||
            'home'
        );

    lastStepValue =
        String(
            getModel()
                .constructor_step ||
            0
        );

    lastGroupsValue =
        String(
            getModel()
                .query_groups_json ||
            '[]'
        );

    lastTargetIdsValue =
        String(
            getModel()
                .query_target_ids_json ||
            '[]'
        );

    lastUseWebValue =
        String(
            getModel()
                .query_use_web ||
            false
        );

    lastAiResponseValue =
        String(
            getModel()
                .ai_response ||
            ''
        );

    lastSelectedQueryIdValue =
        String(
            getModel()
                .selectedQueryId ||
            ''
        );

    lastDrawerPostsValue =
        serializeDrawerPosts(
            getModel()
        );

    lastDrawerAnalyticsValue =
        serializeDrawerAnalytics(
            getModel()
        );


    if (
        typeof appsmith.onModelChange ===
        'function'
    ) {
        appsmith.onModelChange(
            function(newModel) {
                var model =
                    newModel ||
                    getModel();

                var queriesValue =
                    String(
                        model.queries ||
                        ''
                    );

                var targetsValue =
                    String(
                        model.targets ||
                        ''
                    );

                var modeValue =
                    String(
                        model.constructor_mode ||
                        'home'
                    );

                var stepValue =
                    String(
                        model.constructor_step ||
                        0
                    );

                var groupsValue =
                    String(
                        model.query_groups_json ||
                        '[]'
                    );

                var targetIdsValue =
                    String(
                        model.query_target_ids_json ||
                        '[]'
                    );

                var useWebValue =
                    String(
                        model.query_use_web ||
                        false
                    );

                var aiResponseValue =
                    String(
                        model.ai_response ||
                        ''
                    );

                var aiInstructionValue =
                    String(
                        model.ai_instruction ||
                        ''
                    ).trim();

                var selectedQueryIdValue =
                    String(
                        model.selectedQueryId ||
                        ''
                    );

                var sourceManagementValue =
                    getSourceManagementSignature(
                        model
                    );

                var drawerPostsValue =
                    serializeDrawerPosts(
                        model
                    );

                var drawerAnalyticsValue =
                    serializeDrawerAnalytics(
                        model
                    );


                if (
                    aiGenerateArmed &&
                    aiRequestPending &&
                    getMode() === 'ai' &&
                    aiInstructionValue ===
                    aiGenerateInstruction
                ) {
                    aiGenerateArmed =
                        false;

                    appsmith.triggerEvent(
                        'onGenerateAI'
                    );
                }


                if (
                    queriesValue !==
                    lastQueriesValue
                ) {
                    var saveConfirmed =
                        false;

                    if (
                        pendingSaveConfirmation
                    ) {
                        var refreshedQueries =
                            asArray(
                                model.queries
                            );

                        saveConfirmed =
                            refreshedQueries
                                .some(
                                    function(query) {
                                        var queryId =
                                            String(
                                                query &&
                                                query.id ||
                                                ''
                                            ).trim();

                                        var queryName =
                                            String(
                                                query &&
                                                query.name ||
                                                ''
                                            ).trim();

                                        return (
                                            queryId !== '' &&
                                            queryName ===
                                            pendingSaveConfirmation.name &&
                                            pendingSaveConfirmation
                                                .existing_ids
                                                .indexOf(
                                                    queryId
                                                ) ===
                                                -1
                                        );
                                    }
                                );
                    }

                    lastQueriesValue =
                        queriesValue;

                    currentPage =
                        1;

                    renderLibrary();

                    if (
                        saveConfirmed
                    ) {
                        pendingSaveConfirmation =
                            null;

                        resetConstructor();

                        return;
                    }
                }


                if (
                    selectedQueryIdValue !==
                    lastSelectedQueryIdValue
                ) {
                    lastSelectedQueryIdValue =
                        selectedQueryIdValue;

                    renderLibrary();

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }


                if (
                    drawerPostsValue !==
                    lastDrawerPostsValue
                ) {
                    lastDrawerPostsValue =
                        drawerPostsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }


                if (
                    drawerAnalyticsValue !==
                    lastDrawerAnalyticsValue
                ) {
                    lastDrawerAnalyticsValue =
                        drawerAnalyticsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }


                if (
                    sourceManagementValue !==
                    lastSourceManagementValue
                ) {
                    lastSourceManagementValue =
                        sourceManagementValue;

                    if (
                        currentQueryView ===
                        'sources'
                    ) {
                        renderSourcesManagement(
                            model
                        );
                    }
                }


                if (
                    targetsValue !==
                    lastTargetsValue
                ) {
                    lastTargetsValue =
                        targetsValue;

                    if (
                        modeValue ===
                        'manual' &&
                        (
                            stepValue ===
                            '2' ||
                            stepValue ===
                            '3' ||
                            stepValue ===
                            '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }


                if (
                    groupsValue !==
                    lastGroupsValue
                ) {
                    lastGroupsValue =
                        groupsValue;

                    loadGroupsFromModel();

                    if (
                        modeValue ===
                        'manual' &&
                        (
                            stepValue ===
                            '1' ||
                            stepValue ===
                            '3' ||
                            stepValue ===
                            '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }


                if (
                    targetIdsValue !==
                    lastTargetIdsValue ||
                    useWebValue !==
                    lastUseWebValue
                ) {
                    lastTargetIdsValue =
                        targetIdsValue;

                    lastUseWebValue =
                        useWebValue;

                    loadSourcesFromModel();

                    if (
                        modeValue ===
                        'manual' &&
                        (
                            stepValue ===
                            '2' ||
                            stepValue ===
                            '3' ||
                            stepValue ===
                            '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }


                if (
                    aiResponseValue !==
                    lastAiResponseValue
                ) {
                    lastAiResponseValue =
                        aiResponseValue;

                    if (
                        getMode() === 'ai'
                    ) {
                        var aiResponse =
                            asObject(
                                model.ai_response
                            );

                        if (
                            Object.keys(
                                aiResponse
                            ).length > 0 &&
                            (
                                aiResponse.ok === true ||
                                aiResponse.needs_clarification === true
                            )
                        ) {
                            applyAiResponse(
                                aiResponse
                            );
                        }
                    }
                }


                if (
                    modeValue !==
                    lastModeValue ||
                    stepValue !==
                    lastStepValue
                ) {
                    lastModeValue =
                        modeValue;

                    lastStepValue =
                        stepValue;

                    renderCurrentView();
                }
            }
        );
    }
});
